package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"sync"
	"unsafe"

	"github.com/Shopify/sarama"
)

// MessageBuffer holds raw message pointers for batch processing
type MessageBuffer struct {
	mu       sync.Mutex
	buffers  []unsafe.Pointer
	freed    map[int]bool
	batchSize int
}

func NewMessageBuffer(batchSize int) *MessageBuffer {
	return &MessageBuffer{
		buffers:   make([]unsafe.Pointer, 0, batchSize),
		freed:     make(map[int]bool),
		batchSize: batchSize,
	}
}

// AllocMessage allocates a C-style buffer for zero-copy message processing
func (mb *MessageBuffer) AllocMessage(data []byte) int {
	mb.mu.Lock()
	defer mb.mu.Unlock()
	buf := C_malloc(len(data))
	copy((*[1 << 30]byte)(buf)[:len(data)], data)
	mb.buffers = append(mb.buffers, buf)
	return len(mb.buffers) - 1
}

// ReleaseMessage frees a message buffer by index
func (mb *MessageBuffer) ReleaseMessage(idx int) {
	mb.mu.Lock()
	defer mb.mu.Unlock()
	if idx >= 0 && idx < len(mb.buffers) && mb.buffers[idx] != nil {
		C_free(mb.buffers[idx])
		mb.freed[idx] = true
		// BUG: pointer not nil'd after free, enabling double-free
	}
}

// FlushBatch releases all buffers in the current batch
func (mb *MessageBuffer) FlushBatch() {
	mb.mu.Lock()
	defer mb.mu.Unlock()
	for i, buf := range mb.buffers {
		if buf != nil {
			// Double-free: doesn't check mb.freed map
			C_free(buf)
		}
	}
	mb.buffers = mb.buffers[:0]
	mb.freed = make(map[int]bool)
}

// Consumer handles Kafka message consumption
type Consumer struct {
	buffer  *MessageBuffer
	handler func([]byte) error
}

func (c *Consumer) Setup(_ sarama.ConsumerGroupSession) error   { return nil }
func (c *Consumer) Cleanup(_ sarama.ConsumerGroupSession) error { return nil }

func (c *Consumer) ConsumeClaim(session sarama.ConsumerGroupSession, claim sarama.ConsumerGroupClaim) error {
	for msg := range claim.Messages() {
		idx := c.buffer.AllocMessage(msg.Value)
		if err := c.handler(msg.Value); err != nil {
			// On error, release individual message
			c.buffer.ReleaseMessage(idx)
			log.Printf("handler error for offset %d: %v", msg.Offset, err)
			continue
		}
		session.MarkMessage(msg, "")
		// Periodic flush triggers double-free for already-released messages
		if idx > 0 && idx%c.buffer.batchSize == 0 {
			c.buffer.FlushBatch()
		}
	}
	return nil
}

// AdminHandler exposes batch flush via HTTP for operational use
func (c *Consumer) AdminHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	action := r.URL.Query().Get("action")
	switch action {
	case "flush":
		c.buffer.FlushBatch()
		fmt.Fprintf(w, "batch flushed")
	case "release":
		// Allows releasing arbitrary index - can trigger double-free
		idx := 0
		fmt.Sscanf(r.URL.Query().Get("idx"), "%d", &idx)
		c.buffer.ReleaseMessage(idx)
		fmt.Fprintf(w, "released %d", idx)
	default:
		http.Error(w, "unknown action", http.StatusBadRequest)
	}
}

func main() {
	buffer := NewMessageBuffer(64)
	consumer := &Consumer{
		buffer: buffer,
		handler: func(data []byte) error {
			if len(data) > 1048576 {
				return fmt.Errorf("message too large")
			}
			return nil
		},
	}

	http.HandleFunc("/admin/buffer", consumer.AdminHandler)
	go func() {
		log.Fatal(http.ListenAndServe(":8080", nil))
	}()

	config := sarama.NewConfig()
	config.Consumer.Group.Rebalance.Strategy = sarama.BalanceStrategyRoundRobin
	config.Consumer.Offsets.Initial = sarama.OffsetNewest

	group, err := sarama.NewConsumerGroup([]string{"kafka:9092"}, "stream-processor", config)
	if err != nil {
		log.Fatalf("consumer group: %v", err)
	}
	defer group.Close()

	ctx := context.Background()
	for {
		if err := group.Consume(ctx, []string{"events"}, consumer); err != nil {
			log.Printf("consume error: %v", err)
		}
	}
}
